{
  "name": "数字解调模块",
  "name_en": "Digital Demodulation Module",
  "manufacturer": "QuTech",
  "description": "这是一种面向量子测量实验的数字解调仪器，带有ADC通道，用于采集并数字解调读出信号。它可为单边带或双边带读出配置积分权重与旋转矩阵，并支持相关性、误差分数等测量相关设置，常用于超导量子比特读出与状态判别。",
  "description_en": "This is a digital demodulation instrument for quantum measurement experiments, with ADC channels for acquiring and digitally demodulating readout signals. It can be configured with integration weights and rotation matrices for single-sideband or double-sideband readout, and supports measurement-related settings such as correlations and error fractions. It is commonly used for superconducting qubit readout and state discrimination.",
  "tag_hints": [
    "qubit readout",
    "digital demodulation",
    "IQ integration weights",
    "SSB/DSB demodulation",
    "ADC signal acquisition",
    "state discrimination",
    "superconducting qubits"
  ],
  "actions": [
    {
      "action_name": "auto-ask",
      "description": "发送原始SCPI查询并读取设备响应。",
      "description_en": "Send a raw SCPI query to the device and read back the response."
    },
    {
      "action_name": "auto-add_parameter",
      "description": "定义一个设备参数。",
      "description_en": "Define a device parameter."
    },
    {
      "action_name": "auto-add_parameters",
      "description": "读取并定义设备自动生成的参数集合。",
      "description_en": "Read and define the set of automatically generated device parameters."
    },
    {
      "action_name": "auto-add_additional_parameters",
      "description": "查询设备的ADC与量子比特通道配置，并定义附加测量参数。",
      "description_en": "Query the device ADC and qubit-channel configuration and define additional measurement parameters."
    },
    {
      "action_name": "auto-get_time",
      "description": "获取设备系统时间。",
      "description_en": "Get the device system time."
    },
    {
      "action_name": "auto-set_time",
      "description": "设置设备系统时间。",
      "description_en": "Set the device system time."
    },
    {
      "action_name": "auto-get_idn",
      "description": "读取设备身份信息。",
      "description_en": "Read the device identification information."
    },
    {
      "action_name": "auto-connect_message",
      "description": "显示设备连接与身份信息。",
      "description_en": "Display device connection and identification information."
    },
    {
      "action_name": "auto-prepare_SSB_weight_and_rotation",
      "description": "配置单边带解调的积分权重和旋转矩阵。",
      "description_en": "Configure integration weights and rotation matrices for single-sideband demodulation."
    },
    {
      "action_name": "auto-prepare_DSB_weight_and_rotation",
      "description": "配置双边带解调的积分权重和旋转矩阵。",
      "description_en": "Configure integration weights and rotation matrices for double-sideband demodulation."
    },
    {
      "action_name": "auto-log",
      "description": "记录设备通信日志。",
      "description_en": "Record device communication logs."
    }
  ]
}

